metadata.rawInput:
{"command":"python3 << 'EOF'
import re, subprocess, json

UA = "Mozilla/5.0"
def post(url, body):
    r = subprocess.run(["curl","-s","-X","POST",url,
        "-H",f"User-Agent: {UA}",
        "-H","Content-Type: application/json",
        "-d",body], capture_output=True, text=True)
    return r.stdout

ids = {
 "A_LMLYD":"AJtDXIazrMo", "B_Baby":"kffacxfA7G4", "C_OnTheFloor":"t4H_Zoh7G5A",
 "D_UptownFunk":"OPf0YbXqDm0", "E_Attention":"nfs8NYg7yQM", "F_NewRules":"k2qgadSvNyU",
 "G_Sugar":"09R8_2nJtjg", "H_CountingStars":"hT_nvWreIhg", "I_Sorry":"fRh_vgS2dFE",
 "J_WDU":"DK_0jXPuIr0",
}

for name, vid in ids.items():
    body = json.dumps({"context":{"client":{"clientName":"ANDROID","clientVersion":"19.09.37","androidSdkVersion":30,"hl":"en"}},"videoId":vid})
    try:
        data = json.loads(post("https://www.youtube.com/youtubei/v1/player", body))
        sb = data.get("storyboards",{}).get("playerStoryboardSpecRenderer",{}).get("spec","")
        if sb:
            with open(f"sb_{name}.txt","w") as fh: fh.write(sb)
            print(name, vid, "OK", sb[:120].replace("\\/","/"))
        else:
            print(name, vid, "no storyboard; status:", data.get("playabilityStatus",{}).get("status"))
    except Exception as e:
        print(name, vid, "ERR", e)
EOF"}

