python3 << 'EOF'
import numpy as np
from PIL import Image

img = np.asarray(Image.open("barcode.png").convert("RGB"), dtype=np.float32)
h, w, _ = img.shape
mid = img[h//2]
stripes, start = [], 0
for x in range(1, w+1):
    if x == w or not np.array_equal(mid[x], mid[x-1]):
        stripes.append(mid[start:x].mean(axis=0)); start = x
T = np.array(stripes)

cands = np.load("candidate_barcodes.npz")

def smooth(x, k):
    if k <= 1: return x
    pad = np.concatenate([np.repeat(x[:1], k//2, 0), x, np.repeat(x[-1:], k//2, 0)], 0)
    ker = np.ones(k)/k
    return np.stack([np.convolve(pad[:,i], ker, mode='valid') for i in range(3)], axis=1)

def resample(x, n):
    xs = np.linspace(0, 1, len(x)); xt = np.linspace(0, 1, n)
    return np.stack([np.interp(xt, xs, x[:,i]) for i in range(3)], axis=1)

N = 120
Ts = smooth(resample(T, N), 3)

results = {}
for name in cands.files:
    C = cands[name]
    best = 1e9
    # try trims of candidate at both ends (0-8%) and target (0-4%)
    for trim_c0 in [0.0, 0.02, 0.04, 0.06, 0.08]:
        for trim_c1 in [0.0, 0.02, 0.04, 0.06, 0.08]:
            for trim_t in [0.0, 0.02, 0.04]:
                c0 = int(len(C)*trim_c0); c1 = int(len(C)*(1-trim_c1))
                t0 = int(len(T)*trim_t)
                Ct = smooth(resample(C[c0:c1], N), 3)
                Tt = smooth(resample(T[t0:], N), 3)
                d = np.sqrt(((Ct-Tt)**2).mean())
                best = min(best, d)
    results[name] = best
for name, d in sorted(results.items(), key=lambda kv: kv[1]):
    print(f"{name:18s} best-smoothed-RMSE={d:6.2f}")
EOF

